import React, { useState, useEffect } from "react";
import axios from "axios";

const EmployeePage = () => {
  const [employees, setEmployees] = useState([]);
  const [isFormVisible, setIsFormVisible] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [salaryDetails, setSalaryDetails] = useState({
    phone: "",
    startDate: "",
    endDate: "",
    expense: 0,
  });

  // Fetch employees on page load
  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      const { data } = await axios.get("http://localhost:5001/api/employees");
      setEmployees(data);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  };

  const handleAddEmployee = () => {
    setIsFormVisible(true);
    setSelectedEmployee(null); // Clear selected employee for add form
    setSalaryDetails({ phone: "", startDate: "", endDate: "", expense: 0 });
  };

  const handleUpdateEmployee = (employee) => {
    setSelectedEmployee(employee);
    setSalaryDetails({
      phone: employee.phone,
      startDate: employee.startDate || "",
      endDate: employee.endDate || "",
      expense: employee.expense || 0,
    });
    setIsFormVisible(true);
  };

  const handleDateChange = () => {
    if (salaryDetails.startDate && salaryDetails.endDate) {
      const start = new Date(salaryDetails.startDate);
      const end = new Date(salaryDetails.endDate);
      const daysWorked = Math.floor((end - start) / (1000 * 60 * 60 * 24)) + 1;
      console.log("Days Worked:", daysWorked);
    }
  };

  const handleSubmit = async () => {
    try {
      if (selectedEmployee) {
        // Update existing employee
        await axios.put(`http://localhost:5001/api/employees/${selectedEmployee.id}`, salaryDetails);
      } else {
        // Add new employee
        await axios.post("http://localhost:5001/api/employees", salaryDetails);
      }
      setIsFormVisible(false);
      fetchEmployees();
    } catch (error) {
      console.error("Error saving employee details:", error);
    }
  };

  return (
    <div>
      <h1>Employee Management</h1>
      <button onClick={handleAddEmployee}>Add Employee</button>
      <table>
        <thead>
          <tr>
            <th>Phone</th>
            <th>Start Date</th>
            <th>End Date</th>
            <th>Expense</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {employees.map((employee) => (
            <tr key={employee.id}>
              <td>{employee.phone}</td>
              <td>{employee.startDate}</td>
              <td>{employee.endDate}</td>
              <td>{employee.expense}</td>
              <td>
                <button onClick={() => handleUpdateEmployee(employee)}>Update</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {isFormVisible && (
        <div>
          <h3>{selectedEmployee ? "Update Employee Details" : "Add Employee"}</h3>
          <form onSubmit={(e) => e.preventDefault()}>
            <input
              type="text"
              value={salaryDetails.phone}
              onChange={(e) => setSalaryDetails({ ...salaryDetails, phone: e.target.value })}
              placeholder="Phone"
              readOnly={!!selectedEmployee} // Phone number cannot be edited in update form
            />
            <input
              type="date"
              value={salaryDetails.startDate}
              onChange={(e) => {
                setSalaryDetails({ ...salaryDetails, startDate: e.target.value });
                handleDateChange();
              }}
              placeholder="Start Date"
            />
            <input
              type="date"
              value={salaryDetails.endDate}
              onChange={(e) => {
                setSalaryDetails({ ...salaryDetails, endDate: e.target.value });
                handleDateChange();
              }}
              placeholder="End Date"
            />
            <input
              type="number"
              value={salaryDetails.expense}
              onChange={(e) => setSalaryDetails({ ...salaryDetails, expense: e.target.value })}
              placeholder="Expense"
            />
            <button onClick={handleSubmit}>{selectedEmployee ? "Update" : "Add"}</button>
          </form>
        </div>
      )}
    </div>
  );
};

export default EmployeePage;


// Styled Components
const Container = styled.div`
  padding: 20px;
  background-color: #f4f7fc;
`;

const Header = styled.header`
  display: flex;
  justify-content: center;
  padding: 20px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const LorryTitle = styled.h1`
  font-size: 2rem;
  font-weight: bold;
`;

const Button = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  font-size: 1.1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 20px;

  &:hover {
    background-color: #45a049;
  }
`;

const Form = styled.div`
  background-color: #ffffff;
  padding: 20px;
  margin-top: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
`;

const Input = styled.input`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const Select = styled.select`
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ccc;
  border-radius: 5px;
`;

const EmployeeRoles = styled.div`
  margin-top: 30px;
`;

const RoleTabs = styled.div`
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
`;

const Tab = styled.div`
  padding: 10px 20px;
  margin: 0 10px;
  cursor: pointer;
  background-color: #f0f0f0;
  border-radius: 5px;
  font-weight: bold;

  &:hover {
    background-color: #ddd;
  }
`;

const EmployeeList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const EmployeeItem = styled.li`
  font-size: 1rem;
  padding: 5px;
  border-bottom: 1px solid #ccc;
  cursor: pointer;

  &:hover {
    background-color: #f4f4f9;
  }
`;

const EmployeeDetails = styled.div`
  background-color: #fff;
  padding: 20px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 20px;
`;

const DetailsTable = styled.table`
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;

  th,
  td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
  }

  th {
    background-color: #f4f4f4;
    font-weight: bold;
  }
`;

const CardGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 20px;
`;
